import { useState } from 'react';

export default function Heap() {
    const [origin, setOrigin] = useState('center center');
    const [rotation, setRotation] = useState(0);

    // Simulating changing the origin AFTER rotation animation finishes
    const updatePivotAfterAnimation = () => {
        // Changing this won't break the node because rotation lives inside
        setOrigin('top left');
    };

    return (
        <div style={{ padding: '40px', fontFamily: 'sans-serif' }}>

            {/* Outer Wrapper: Controls the dynamic transform-origin pivot */}
            <div
                style={{
                    transformOrigin: origin,
                    display: 'inline-block',
                    border: '2px dashed #cbd5e1', // To visualize the pivot container
                    padding: '10px'
                }}
            >
                {/* Inner Wrapper: Controls the rotation independent of the pivot */}
                <div
                    style={{
                        transform: `rotate(${rotation}deg)`,
                        transition: 'transform 0.5s ease-in-out',
                        width: '80px',
                        height: '80px',
                        background: '#3b82f6',
                        color: 'white',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        borderRadius: '8px',
                        fontWeight: 'bold'
                    }}
                >
                    Node
                </div>
            </div>

            <div style={{ marginTop: '20px', display: 'flex', gap: '10px' }}>
                <button onClick={() => setRotation(45)}>
                    Rotate Node (45°)
                </button>
                <button onClick={updatePivotAfterAnimation}>
                    Change Transform-Origin Now
                </button>
            </div>

        </div>
    );
}
